import 'package:flutter_test/flutter_test.dart';import 'package:internal_chat/models/api_result.dart';import 'package:internal_chat/models/authentication.dart';import 'package:internal_chat/models/user.dart';import 'package:internal_chat/modules/authentication/authentication_controller.dart';import 'package:internal_chat/repositories/authentication_repository.dart';
class FakeAuthenticationRepository implements AuthenticationRepository{bool called=false;@override Future<ApiResult<AuthenticationOutcome>> signIn({required String identifier,required String password})async{called=true;return const ApiSuccess(Authenticated(User(id:'1',displayName:'Contract User',email:'user@example.invalid'),AuthTokens(accessToken:'test-token')));}@override Future<User?> currentUser()async=>null;@override Future<void> signOut()async{}@override Future<ApiResult<Authenticated>> verifyMfa({required String challengeId,required String code})async=>throw UnimplementedError();}
void main(){test('authentication controller uses repository contract and stores result',()async{final repository=FakeAuthenticationRepository();final controller=AuthenticationController(repository);expect(await controller.signIn('user','password'),isTrue);expect(repository.called,isTrue);expect(controller.user.value?.displayName,'Contract User');expect(controller.user.value?.id,'1');});}
